    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

model = cp.Model()

# Decision variables: mines[i][j] = 1 if cell (i,j) is a mine, else 0
mines = [[cp.intvar(0,1,name=f"m_{i}_{j}") for j in range(cols)] for i in range(rows)]

# Helper to get neighbors coordinates
def neighbors(r,c):
    for dr in [-1,0,1]:
        for dc in [-1,0,1]:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not (nr == r and nc == c):
                    yield nr,nc

# Constraints from clues
for i in range(rows):
    for j in range(cols):
        clue = game_data[i][j]
        if clue != X:
            # sum of mines around this cell must be equal to clue
            nbrs = [mines[nr][nc] for (nr,nc) in neighbors(i,j)]
            model += (cp.sum(nbrs) == clue)

# For cells that are open (not X), mines[i][j] must be 0
for i in range(rows):
    for j in range(cols):
        if game_data[i][j] != X:
            model += (mines[i][j] == 0)

if model.solve():
    solution = {'mines': [ [int(mines[i][j].value()) for j in range(cols)] for i in range(rows)]}
    print(json.dumps(solution, indent=4))
else:
