import cpmpy as cp
import json
import numpy as np

X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

# Convert input to numpy array for easier indexing
game_data_np = np.array(game_data)

# Decision variable: mines[i,j] = 1 if cell (i,j) contains a mine, 0 otherwise
mines = cp.intvar(0, 1, shape=(rows, cols), name="mines")

model = cp.Model()

# Constraint: cells that are opened and have number != X are NOT mines
for i in range(rows):
    for j in range(cols):
        if game_data_np[i, j] != X:
            model += (mines[i, j] == 0)

# For each cell that has a number (0-8), the sum of mines in adjacent cells must equal that number
# Adjacent cells include diagonals, so up to 8 neighbors
for i in range(rows):
    for j in range(cols):
        clue = game_data_np[i, j]
        if clue != X:
            neighbors = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        if not (ni == i and nj == j):
                            neighbors.append(mines[ni, nj])
            if neighbors:
                model += (cp.sum(neighbors) == clue)
            else:
                # No neighbors, clue should be zero
                model += (clue == 0)

# Solve model
if model.solve():
    # Extract mines decision variables as int lists
    solution = {'mines': mines.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
